                    .eq(UserBehaviorStats::getStatHour, hour)
                    .eq(UserBehaviorStats::getUserId, userId)
            );
            if (existing != null) {
                stats.setId(existing.getId());
                statsMapper.updateById(stats);
            } else {
                statsMapper.insert(stats);
            }
